import{_ as o,o as e,c as n,a3 as r}from"./chunks/framework.I6s8z2kk.js";const m=JSON.parse('{"title":"Promotions, campaigns and coupons","description":"","frontmatter":{},"headers":[],"relativePath":"user/admin/promotions.md","filePath":"user/admin/promotions.md"}'),s={name:"user/admin/promotions.md"};function a(i,t,d,c,g,h){return e(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="promotions-campaigns-and-coupons" tabindex="-1">Promotions, campaigns and coupons <a class="header-anchor" href="#promotions-campaigns-and-coupons" aria-label="Permalink to &quot;Promotions, campaigns and coupons&quot;">​</a></h1><h2 id="promotions" tabindex="-1">Promotions <a class="header-anchor" href="#promotions" aria-label="Permalink to &quot;Promotions&quot;">​</a></h2><p>A promotion is a discount rule. Create it from <strong>Marketing → Promotions → New</strong>. It starts as a <strong>draft</strong> and does nothing until you <strong>activate</strong> it.</p><h3 id="main-choices" tabindex="-1">Main choices <a class="header-anchor" href="#main-choices" aria-label="Permalink to &quot;Main choices&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Options</th></tr></thead><tbody><tr><td><strong>Scope</strong></td><td><strong>Item:</strong> each matching service line. <strong>Order:</strong> the whole purchase.</td></tr><tr><td><strong>Discount</strong></td><td><strong>Percentage</strong>, <strong>fixed amount</strong> off, or <strong>fixed price</strong> (the item becomes this price)</td></tr><tr><td><strong>Maximum discount</strong></td><td>A cap, useful with percentages</td></tr><tr><td><strong>Minimum spend</strong></td><td>The eligible items must reach this amount</td></tr><tr><td><strong>Center</strong></td><td>One center, or empty for a platform-wide offer</td></tr><tr><td><strong>Funded by</strong></td><td><strong>Platform</strong>, <strong>center</strong>, or <strong>shared</strong> (with the center&#39;s share)</td></tr><tr><td><strong>Stacking</strong></td><td><strong>Stackable</strong> combines with other offers. <strong>Exclusive</strong> does not.</td></tr><tr><td><strong>Priority</strong></td><td>Breaks ties between two equally good offers</td></tr><tr><td><strong>Dates</strong> and <strong>weekly schedule</strong></td><td>When it runs</td></tr><tr><td><strong>Targets</strong></td><td>Which services it includes or excludes</td></tr><tr><td><strong>Needs a coupon</strong></td><td>Applies only when the client enters a code</td></tr></tbody></table><h3 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h3><p><strong>Draft → Active ⇄ Paused → Archived.</strong> You can pause and resume. An archived promotion is read-only.</p><p>Once a promotion has been used in a purchase, its scope, discount, maximum and targets are <strong>locked</strong>. To change them, archive it and create a new one.</p><h3 id="how-offers-combine" tabindex="-1">How offers combine <a class="header-anchor" href="#how-offers-combine" aria-label="Permalink to &quot;How offers combine&quot;">​</a></h3><ul><li>Each line gets <strong>at most one item offer</strong>: the biggest discount wins.</li><li><strong>At most one order offer</strong> is added on top.</li><li>An <strong>exclusive</strong> offer stops other offers from stacking with it.</li><li>A discount never goes below zero.</li></ul><h2 id="campaigns" tabindex="-1">Campaigns <a class="header-anchor" href="#campaigns" aria-label="Permalink to &quot;Campaigns&quot;">​</a></h2><p>A campaign groups promotions under one marketing banner (for example a season). It can be featured on the <a href="./homepage">homepage</a>.</p><h2 id="coupons" tabindex="-1">Coupons <a class="header-anchor" href="#coupons" aria-label="Permalink to &quot;Coupons&quot;">​</a></h2><p>Coupons unlock a promotion that needs a code. Create them one by one or <strong>generate</strong> a batch. Codes are saved in capitals. You can limit total uses and uses per client, and <strong>assign</strong> a coupon to specific clients.</p><p>Clients see the offer in the app only while it is running and has uses left.</p><h2 id="seeing-results" tabindex="-1">Seeing results <a class="header-anchor" href="#seeing-results" aria-label="Permalink to &quot;Seeing results&quot;">​</a></h2><p>Open a promotion&#39;s <strong>Redemptions</strong> to see where it was used, and <strong>Analytics → Promotions</strong> for totals.</p>',17)])])}const p=o(s,[["render",a]]);export{m as __pageData,p as default};
